    int b   = idx / (B_oc * L_out);
    int tmp = idx % (B_oc * L_out);
    int oc  = tmp / L_out;
    int lo  = tmp % L_out;

    // Group handling
    int oc_per_group = B_oc / groups;
    int ic_per_group = B_ic / groups;
    int group_id = oc / oc_per_group;
    int icg_base = group_id * ic_per_group;

    float acc = 0.0f;

    // Convolution loop
    for (int icg = 0; icg < ic_per_group; ++icg) {
        int ic = icg_base + icg;
        for (int k = 0; k < B_k; ++k) {
            int li = lo * stride - padding + k * dilation;
            if (li >= 0 && li < B_l_in) {
                // A layout: (B, IC, L_in) -> offset = ((b * B_ic + ic) * B_l_in + li)
                // W layout: (OC, IC_g, K) -> offset = ((oc * ic_per_group + icg) * B_k + k)
                __half a = A[((b * B_ic + ic) * B_l_in) + li];
                __half w = W[((oc * ic_per_group + icg) * B_k) + k];
                acc += __half2float(a) * __half2float(w);
            }
        }
    }

    // Add bias if present
    if (B != nullptr) {
        acc += __half2float(B[oc]);
    }

    // Write result
    C[idx] = __float2half(acc);
}
