        w = torch.empty(
            out_channels,
            in_channels // groups,
            kernel_size,
            dtype=torch.float16,
            device="cuda",
        )
        nn.init.kaiming_uniform_(w, a=math.sqrt(5))
        self.weight = nn.Parameter(w)

        if bias:
            b = torch.empty(out_channels, dtype=torch.float16, device="cuda")
            fan_in = in_channels * kernel_size
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (B, IC, L_in)  fp16 tensor on CUDA
        returns: (B, OC, L_out) fp16 tensor on CUDA
        """
        B, IC, L_in = x.shape
        L_out = (L_in + 2 * self.padding -
                 self.dilation * (self.kernel_size - 1) - 1) // self.stride + 1

        out = torch.empty(
            B, self.out_channels, L_out,
            dtype=torch.float16,
            device="cuda",
        )

        # Launch kernel
        threads = 256
        total = B * self.out_channels * L_out
        blocks = (total + threads - 1) // threads

        conv1d_kernel.conv1d_fp16(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([], dtype=torch.float16, device='cuda').data_ptr(),
            out,
            B,
            IC,
            L_in,
            self.out_channels,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
            grid=(blocks,),
            block=(threads,),
        )
        return out

